/// <summary>
/// Batch service class for Recalculate attribute cache
/// </summary>
public class METRecalculateArrtibuteCacheService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Processes the supplied <see cref="METRecalculateArrtibuteCacheContract"/> and recalculates the attribute cache
/// for each matching <see cref="InventTable"/> record returned by the contract query.
/// </summary>
/// <param name="_contract">
/// The contract that provides the <c>Query</c> used to select <see cref="InventTable"/> records and flags that
/// control behavior (for example, <c>parmUpdateParameters()</c> and <c>parmDisplayInfoOnUpdate()</c>).
/// </param>
public void process(METRecalculateArrtibuteCacheContract _contract)
{
    #OCCRetryCount
    InventTable             inventTable;
    METUpdateParameters     updateParameters;
    METDisplayInfoOnUpdate  displayInfoOnUpdate;
    EcoResProductParameters ecoResProductParameters = EcoResProductParameters::find();
    METCachedAttributes     cachedAttributes = METCachedAttributes::find();
    METGetAttributeValue    getAttributeValue;
    Query                   query = _contract.getQuery();
    QueryRun                queryRun = new QueryRun(query);
    int                     recordsProcessed, erroredRecords; 

    updateParameters = _contract.parmUpdateParameters();
    displayInfoOnUpdate = _contract.parmDisplayInfoOnUpdate();

    if (updateParameters)
    {
        ttsbegin;
        ecoResProductParameters.selectForUpdate(true);
        ecoResProductParameters.METUseCachedAttributes = METUseCachedAttributesEnum::NoTrackValues;
        ecoResProductParameters.update();
        ttscommit;
    }

    ttsbegin;
    while (queryRun.next())
    {
        ++recordsProcessed;

        try                
        {
            inventTable = queryRun.get(tableNum(InventTable));

            getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
            getAttributeValue.setAttributeValues(cachedAttributes, displayInfoOnUpdate);
        }
        catch (Exception::Deadlock)
        {
            // Retry logic for deadlocks
            if (xSession::currentRetryCount() < #RetryNum)
            {
                retry;
            }
            else
            {
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            // Retry logic for update conflicts
            if (appl.ttsLevel() == 0 && xSession::currentRetryCount() < #RetryNum)
            {
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        catch (Exception::Error)
        {
            ++erroredRecords;
            // Catch any exception so that one error won't stop the entire process.
            Global::exceptionTextFallThrough();
            continue;
        }
    }

    if (updateParameters)
    {
        ecoResProductParameters.selectForUpdate(true);
        ecoResProductParameters.METUseCachedAttributes = METUseCachedAttributesEnum::Yes;
        ecoResProductParameters.update();
    }
    ttscommit;

    Info(strFmt("@MET:AttributeCacheValueProcessed", recordsProcessed, erroredRecords));      
}
